package cn.zhuatech.mes.controller; import cn.zhuatech.mes.common.ApiResponse; import cn.zhuatech.mes.dto.MesDto.*; import cn.zhuatech.mes.service.MesService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public class ShopfloorController {private final MesService mes;public ShopfloorController(MesService mes){this.mes=mes;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(mes.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("报工提交成功",mes.report(id,request));}}
